from pathlib import Path
import json,re,subprocess,hashlib
B=Path(__file__).resolve().parent;R=B.parent;E=B/'a_amortized-evidence'
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
specs=[]
def model(id,title,**spec):specs.append(dict(id=id,title=title,spec=spec))
model('counter17','Seventeen increments from zero, six-bit storage',kind='counter',count=17,width=6)
model('counter-carry','Five trailing ones: 31 to 32',kind='counter',start=31,count=1,width=6)
model('counter-wrap','Four-bit counter: sixteen increments including wrap',kind='counter',count=16,width=4)
model('counter-nonzero','Five-bit counter: 30 to 31 to 0 to 1',kind='counter',count=3,width=5,start=30)
model('growth8','Eight appends: filling capacity eight without copying it',kind='growth',count=8)
model('growth9','Nine appends: the first append beyond capacity eight',kind='growth',count=9)
model('growth-round','Growth factor three halves with integer capacities',kind='growth',count=9,factor=1.5)
model('shrink16','Quarter shrink: size five/capacity sixteen, then pop',kind='shrink',size=5,capacity=16,operations=[dict(type='pop')])
model('shrink4','Smallest shrink: size two/capacity four, then pop',kind='shrink',size=2,capacity=4,operations=[dict(type='pop')])
model('midpoint','Cross the potential midpoint at size four/capacity eight',kind='shrink',size=4,capacity=8,operations=[dict(type='pop')])
model('mixed-array','Interleaved appends and post-removal quarter shrinking',kind='shrink',size=0,capacity=2,operations=[dict(type='append')for _ in range(9)]+[dict(type='pop')for _ in range(9)])
model('thrash','Half-threshold counterexample: size five/capacity eight',kind='thrash',size=5,capacity=8,operations=[dict(type=t)for t in ['pop','append']*3])
model('queue12','Twelve enqueues followed by five dequeues',kind='queue',operations=[dict(type='enqueue',value=i)for i in range(1,13)]+[dict(type='dequeue')for _ in range(5)])
model('queue-interleave','Queue input 1,2,3; dequeue; input 4,5; three dequeues',kind='queue',operations=[dict(type='enqueue',value=i)for i in [1,2,3]]+[dict(type='dequeue')]+[dict(type='enqueue',value=i)for i in [4,5]]+[dict(type='dequeue')for _ in range(3)])
model('monotonic','Strict dominance in [3,1,4,2,5]',kind='monotonic',values=[3,1,4,2,5])
model('ties-strict','Equal values remain under strict-smaller dominance',kind='monotonic',values=[4,4,4])
model('ties-inclusive','Later equal values replace earlier candidates',kind='monotonic',values=[4,4,4],equal=True)
model('multipop','Push 4,8,3; remove two; push 9; bounded remove five',kind='multipop',operations=[dict(type='push',value=i)for i in[4,8,3]]+[dict(type='multipop',k=2),dict(type='push',value=9),dict(type='multipop',k=5)])
model('blocks8','Eight singleton insertions into binary sorted blocks',kind='blocks',count=8)
model('migration','Four old records: copy one per append into eight slots',kind='migration')
save(E/'model-specs.json',specs)
node="const h=require('./dist/chapters/a_amortized.js'),fs=require('fs'); const a=JSON.parse(fs.readFileSync('research/a_amortized-evidence/model-specs.json'));process.stdout.write(JSON.stringify(a.map(x=>h.makeModel(x.id,x.title,x.spec))))"
models=json.loads(subprocess.run(['node','-e',node],cwd=R,capture_output=True,text=True,check=True).stdout)
groups=dict(counter=['counter17','counter-carry','counter-wrap','counter-nonzero'],growth=['growth8','growth9','growth-round'],shrinking=['shrink16','shrink4','midpoint','mixed-array','thrash'],queue=['queue12','queue-interleave'],monotonic=['monotonic','ties-strict','ties-inclusive'],stack=['multipop'],blocks=['blocks8'],migration=['migration'])
save(R/'dist/chapters/a_amortized-models.json',dict(models=models,groups=groups))
renderer=(B/'render_a_hash.py').read_text(encoding='utf-8').replace('a_hash','a_amortized').replace('hs-','am-').replace('#hs','#am').replace('21 specialized exact hashing models','20 specialized exact-cost models').replace('82 worked problems','87 worked problems').replace('questionCount=82','questionCount=87').replace('originalQuestionCount=80','originalQuestionCount=85').replace('animationCount=21','animationCount=20').replace('animationWalkthroughCount=21','animationWalkthroughCount=20').replace('four core written university courses plus two reviewed comparisons','four core written university courses plus one reviewed comparison')
renderer=renderer.replace("Phi='Φ')","Phi='Φ',Psi='Ψ',Omega='Ω')")
renderer=renderer.replace('<!-- INCLUDE: problems -->','<!-- QUESTIONS -->').replace('<!-- INCLUDE: review -->','<!-- RULES -->').replace('<!-- LAB: hash -->','<!-- LAB -->').replace("==82 and body.count","==87 and body.count")
a=renderer.index("lab='");b=renderer.index("\n",a)
lab='<section class="lab"><form id="am-form"><label>Mechanism<select name="kind"><option>growth</option><option>counter</option><option>monotonic</option><option>blocks</option></select></label><label>Operation count<input name="count" value="9"></label><label>Counter width<input name="width" value="5"></label><label>Initial counter value<input name="start" value="0"></label><label>Growth factor<select name="factor"><option>2</option><option>1.5</option><option>3</option></select></label><label>Monotonic input values<input name="values" value="3,1,4,2,5"></label><label><input type="checkbox" name="equal">Pop equal candidates as well</label><button type="submit">Build the exact-cost trace</button></form><p id="am-error" role="alert"></p><p>Use zero through thirty-two operations, a counter width of two through six and an initial value representable by that width. Sorted-block examples accept at most sixteen insertions. Monotonic input accepts at most twelve integers between minus ninety-nine and ninety-nine. Counter arithmetic wraps at its declared width. Growth charges record copies and writes; allocation is excluded. Monotonic comparisons are shown separately from stack modifications. Large arrays show the first sixteen storage positions and retain the full state in the exact snapshot. Every trace starts paused; invalid input preserves the preceding valid experiment.</p><div id="am-output"></div></section>'
renderer=renderer[:a]+'lab='+repr(lab)+renderer[b:]
renderer=renderer.replace("title='Hash Tables: Exact Probes, Collision Mathematics, and Correct Updates'","title='Amortized Analysis and Dynamic Resizing'")
renderer=re.sub(r"anchors=\[[^\n]+?\];it=iter\(anchors\)","anchors=['sources','contract','aggregate','accounting','potential','design','multipop','counter','arrays','growth','weighted','thrashing','shrinking','hysteresis','queue','monotonic','blocks','advanced','boundaries','exam-reasoning','summary','problems','review','laboratory','references'];it=iter(anchors)",renderer)
renderer=renderer.replace('Hashing chapter audit','Amortized-analysis chapter audit').replace('Hashing chapter</a>','Amortized-analysis chapter</a>')
(B/'render_a_amortized.py').write_text(renderer,encoding='utf-8')
css='''.am-model{max-width:760px;margin:1.5rem auto;padding:1.1rem;border:1px solid #d3e1e6;border-radius:12px;background:#f9fcfc;break-inside:avoid}.am-model h3{font-family:Newsreader,serif;font-weight:450;margin-top:0}.am-stage{overflow:auto;max-height:420px;contain:inline-size}.am-stage svg{display:block;width:760px;min-width:680px;max-width:none;height:auto}.am-prose{font-family:"Source Sans 3",sans-serif;font-size:17px;fill:#163d55}.am-value{font-family:"STIX Two Math",serif;font-size:16px;fill:#163d55;text-anchor:middle}.am-index{font-family:"STIX Two Math",serif;font-size:14px;text-anchor:middle;fill:#385d6e}.am-math{font-family:"STIX Two Math",serif;font-size:17px;fill:#163d55}.am-id{font-family:"STIX Two Math",serif;font-size:12px;text-anchor:middle;fill:#557784}.am-block{font-family:"STIX Two Math",serif;font-size:14px;fill:#163d55}.am-formula math{font-family:"STIX Two Math",serif}.am-print{display:none}#am-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}#am-form label{display:grid;gap:.45rem;min-width:0}#am-form input,#am-form select{font:inherit;padding:.55rem .7rem;border:1px solid #b4cbd2;border-radius:6px;min-width:0;width:100%;box-sizing:border-box;background:white}#am-form input{font-family:"JetBrains Mono",monospace;font-size:.9rem}#am-form input[type=checkbox]{width:auto}#am-form button{font:inherit;border:1px solid #a8c4cb;background:#e7f1f2;border-radius:7px;padding:.7rem;cursor:pointer}#am-error{color:#a03040}.lesson pre{overflow:auto;contain:inline-size}.formula-block{overflow-x:auto}.am-model a,.lesson a,a:hover,a:focus,summary{text-decoration:none!important}@media(max-width:650px){#am-form{grid-template-columns:1fr}.am-model{padding:1rem}}@media print{#am-form,#am-error,.am-stage{display:none!important}.am-model{padding:12px;background:white;break-inside:auto}.am-print{display:block}.am-print figure{margin:1rem 0;break-inside:avoid}.am-print svg{width:100%;height:auto}.am-print figcaption{font-size:10pt}}'''
(R/'dist/chapters/a_amortized.css').write_text(css,encoding='utf-8')
acq=json.loads((E/'acquisition.json').read_text(encoding='utf-8'))
save(E/'reading.json',dict(status='reviewed_written_sources',candidateUniversities=8,coreUniversities=['MIT','CMU','Princeton','Stanford'],additionalUniversities=['ETH Zurich'],readRanges=dict(MIT='All nine Lecture 11 PDF pages via official web text.',CMU='All eleven Lecture 6 PDF pages via official web text.',Princeton='All 49 native slide pages.',Stanford='All 79 native condensed slide pages.',ETH='All 57 native handout pages; amortization pages14–29 and competitive analysis34–45.'),nativeHashes=[x for x in acq if x.get('sha256')],limits='Cambridge, Berkeley and Oxford screened but not counted as read; no global-all-courses claim.'))
print('Prepared',len(models),'models /',sum(len(m['frames'])for m in models),'checkpoints and dedicated renderer.')
